UPDATE lancamento_campos SET origem = (SELECT trim('o parcelamento ' || p.descricao) FROM lancamentos l JOIN parcelamentos p ON p.id = l.parcelamento_id WHERE l.id = lancamento_campos.lancamento_id) WHERE (lancamento_id, campo) IN (SELECT c.lancamento_id, c.campo FROM lancamento_campos c JOIN edicao_em_lote_lancamentos e ON e.lancamento_id = c.lancamento_id AND e.versao = c.versao JOIN lancamentos l ON l.id = c.lancamento_id JOIN parcelamentos p ON p.id = l.parcelamento_id WHERE c.origem IS NULL AND c.campo IN ('categoria_ids', 'tags', 'item_categoria_id') LIMIT 3000)
